 * Inserts a cloned project and, in the same transaction, fresh copies of the
 * given source issues numbered from 1 in the order supplied. Either all of it
 * is written or none of it.
 */
export async function insertClonedProject(
  source: Project,
  target: { name: string; slug: string; key: string },
  sourceIssues: readonly Issue[],
  authorId: UserId,
  status: IssueStatus,
): Promise<Project> {
  const db = getDb();
  const taken = await listTakenProjectSlugs(source.orgId);
  const slug = uniqueSlug(target.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = db.transaction((tx) => {
    const project = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: source.orgId,
        name: target.name,
        slug,
        key: target.key,
        description: source.description,
        visibility: source.visibility,
        status: "active",
        leadId: source.leadId,
        color: source.color,
        startsAt: null,
        targetDate: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    sourceIssues.forEach((issue, index) => {
      const id = newId();
      tx.insert(issues)
        .values({
          id,
          orgId: source.orgId,
          projectId: project.id,
          number: index + 1,
          title: issue.title,
          description: issue.description,
          status,
          priority: issue.priority,
          authorId,
          assigneeId: null,
          parentId: null,
          estimate: issue.estimate,
          dueAt: issue.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (issue.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            issue.labelIds.map((labelId) => ({
              orgId: source.orgId,
              issueId: id,
              labelId,
            })),
          )
          .run();
      }
    });

    return project;
  });

  return toProject(row);
}

